import { useState, useEffect } from 'react';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';
import UploadForm from '../components/UploadForm';

const Gallery = () => {
  const [images, setImages] = useState([]);
  const { user } = useAuth();

  useEffect(() => {
    fetchImages();
  }, []);

  const fetchImages = async () => {
    try {
      const { data } = await axios.get('/api/gallery');
      setImages(data);
    } catch (error) {
      console.error('Error fetching images:', error);
    }
  };

  const handleLike = async (id) => {
    try {
      await axios.put(`/api/gallery/${id}/like`, {}, {
        headers: { Authorization: `Bearer ${user.token}` },
      });
      fetchImages(); // ✅ Refresh after like
    } catch (error) {
      alert(error.response?.data?.message || 'Error liking image');
    }
  };

  const handleUnlike = async (id) => {
    try {
      await axios.put(`/api/gallery/${id}/unlike`, {}, {
        headers: { Authorization: `Bearer ${user.token}` },
      });
      fetchImages(); // ✅ Refresh after unlike
    } catch (error) {
      alert(error.response?.data?.message || 'Error unliking image');
    }
  };

  return (
    <div className="container mt-4">
      {/* ✅ Only Admin Can See Upload Option */}
      {user?.role === 'admin' && (
        <UploadForm onUploadSuccess={fetchImages} />
      )}

      <div className="row">
        {images.map((image) => (
          <div key={image._id} className="col-md-4 mb-3">
            <div className="card">
              <img src={image.imageUrl} alt="Gallery" className="card-img-top" />
              <div className="card-body">
                <p className="card-text">Uploaded by: {image.uploadedBy?.name}</p>
                <p>{image.likes.length} likes</p>
                {image.likes.includes(user._id) ? (
                  <button onClick={() => handleUnlike(image._id)} className="btn btn-danger">
                    Unlike
                  </button>
                ) : (
                  <button onClick={() => handleLike(image._id)} className="btn btn-primary">
                    Like
                  </button>
                )}
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Gallery;
